// =========================================================================
// ABC Tech — Workflow 3: Phản hồi định kỳ & Quản trị hiệu suất (WF3)
// Phụ trách phát triển: Trần Vĩnh Thịnh (thinhtv104)
// Đề tài: Chuyên đề 2 - Tự động hóa HR bằng n8n & Trí tuệ nhân tạo (AI)
// Cập nhật: 23/10/2026
// =========================================================================

const raw = $input.first().json;
const data = (raw && raw.body && typeof raw.body === 'object') ? { ...raw, ...raw.body } : (raw || {});
const clean = (v, maxLen) => String(v ?? '').trim().slice(0, maxLen);

const employee_id = clean(data.employee_id, 20).toUpperCase();
const period = clean(data.period, 20);
let satisfaction = parseInt(String(data.satisfaction).slice(0, 1), 10);
if (isNaN(satisfaction) || satisfaction < 1 || satisfaction > 5) {
  satisfaction = 3;
}
const feedback_text = clean(data.feedback_text, 2000);
const need_support = (data.need_support === true || data.need_support === 'true' || String(data.need_support || '').toLowerCase().includes('có') || satisfaction <= 2);
const employee_email = clean(data.employee_email || data.demo_email || '', 254).toLowerCase();
const hr_email = clean(data.hr_email || 'whateverholding246@gmail.com', 254).toLowerCase();

return [{
  json: {
    employee_id,
    period,
    satisfaction,
    feedback_text,
    need_support,
    employee_email,
    hr_email,
    demo_email: employee_email,
    received_at: new Date().toISOString()
  }
}];

// =========================================================================
// Module đối chiếu & tính toán chỉ số KPI: Tỷ lệ (%) = (Thực tế / Mục tiêu) * 100
// Phụ trách: Trần Vĩnh Thịnh (thinhtv104)
// =========================================================================

const kpi = $input.first().json;
const actual = parseFloat(kpi.Actual ?? kpi.actual) || 0;
const target = parseFloat(kpi.Target ?? kpi.target) || 1;
const percentage = Math.round((actual / target) * 100);
let kpi_status = 'Đạt kỳ vọng';
if (percentage < 70) kpi_status = 'Cần cải thiện';
else if (percentage < 90) kpi_status = 'Tiệm cận mục tiêu';
else if (percentage >= 100) kpi_status = 'Vượt mục tiêu';

return [{
  json: {
    ...kpi,
    actual,
    target,
    kpi_score: percentage,
    kpi_percentage: percentage + '%',
    kpi_status,
    has_kpi: true
  }
}];

const rawText = String($input.first().json.text || '');

let topic = rawText.match(/TOPIC:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let ai_summary = rawText.match(/SUMMARY:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let suggested_action = rawText.match(/ACTION:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let sentiment = rawText.match(/SENTIMENT:\s*([^\n\r]+)/i)?.[1]?.trim() || 'Cần lưu ý';

if (!topic) {
  try {
    const clean = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(clean);
    topic = parsed.topic;
    ai_summary = parsed.ai_summary;
    suggested_action = parsed.suggested_action;
    sentiment = parsed.sentiment || 'Cần lưu ý';
  } catch {}
}

let lower = String(topic || '').toLowerCase();
if (lower.includes('đào tạo') || lower.includes('hướng dẫn') || lower.includes('training')) topic = 'training';
else if (lower.includes('công cụ') || lower.includes('phần mềm') || lower.includes('thiết bị') || lower.includes('tool')) topic = 'tools';
else if (lower.includes('khối lượng') || lower.includes('quá tải') || lower.includes('lương') || lower.includes('workload')) topic = 'workload';
else if (lower.includes('quy trình') || lower.includes('tài liệu') || lower.includes('ca trực') || lower.includes('môi trường') || lower.includes('process')) topic = 'process';
else topic = 'process';

if (!ai_summary) ai_summary = rawText.slice(0, 250) || 'Nhân viên cần hướng dẫn quy trình công việc.';
if (!suggested_action) suggested_action = 'HR trao đổi với Quản lý để cập nhật tài liệu hướng dẫn và hỗ trợ nhân viên.';

const emp = $('Đọc hồ sơ từ Employees').first().json;
const full_name = emp['Full Name'] || emp.full_name || 'Nhân viên ABC Tech';
const department = emp['Department'] || emp.department || 'Vận hành';
const job_title = emp['Job ID'] || emp.job_title || 'Chuyên viên';
const emp_email_sheet = emp['Email'] || emp.email;

const inputData = $('Chuẩn hóa dữ liệu tiếp nhận').first().json;
const kpiData = $('Tính toán tỷ lệ hoàn thành KPI').first()?.json || $('Gán mặc định khi thiếu KPI').first()?.json || {};

const feedback_id = 'FB-' + inputData.employee_id + '-' + $execution.id;
const employee_email = inputData.employee_email || emp_email_sheet || 'thinhzxc124@gmail.com';
const hr_email = inputData.hr_email || 'whateverholding246@gmail.com';

return [{
  json: {
    feedback_id,
    employee_id: inputData.employee_id,
    full_name,
    email: employee_email,
    employee_email,
    hr_email,
    demo_email: employee_email,
    department,
    job_title,
    period: inputData.period,
    satisfaction: inputData.satisfaction,
    feedback_text: inputData.feedback_text,
    need_support: inputData.need_support,
    kpi_score: kpiData.kpi_score ?? 0,
    kpi_percentage: kpiData.kpi_percentage ?? '0%',
    actual: kpiData.actual ?? 0,
    target: kpiData.target ?? 0,
    kpi_status: kpiData.kpi_status ?? 'Chưa có KPI',
    has_kpi: kpiData.has_kpi ?? false,
    topic,
    ai_summary,
    suggested_action,
    sentiment,
    created_at: new Date().toISOString()
  }
}];
